CREATE TABLE roles (id CHAR(36) PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE permissions (id CHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE role_permissions (role_id CHAR(36), permission_id CHAR(36), PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE users (id CHAR(36) PRIMARY KEY, role_id CHAR(36) NOT NULL, name VARCHAR(150) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, deleted_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE user_permissions (user_id CHAR(36), permission_id CHAR(36), PRIMARY KEY(user_id,permission_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE sectors (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(140) UNIQUE, description TEXT, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE services (id CHAR(36) PRIMARY KEY, sector_id CHAR(36) NULL, name VARCHAR(120) NOT NULL, slug VARCHAR(140) UNIQUE, description TEXT, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(sector_id) REFERENCES sectors(id));
CREATE TABLE stages (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, description TEXT, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE teams (id CHAR(36) PRIMARY KEY, sector_id CHAR(36), service_id CHAR(36), name VARCHAR(120) NOT NULL, description TEXT, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(sector_id) REFERENCES sectors(id), FOREIGN KEY(service_id) REFERENCES services(id));
CREATE TABLE shifts (id CHAR(36) PRIMARY KEY, name VARCHAR(50) NOT NULL, display_order INT DEFAULT 0, description TEXT, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE service_stages (id CHAR(36) PRIMARY KEY, service_id CHAR(36) NOT NULL, stage_id CHAR(36) NOT NULL, team_id CHAR(36), display_order INT NOT NULL, is_required BOOLEAN DEFAULT TRUE, is_active BOOLEAN DEFAULT TRUE, UNIQUE(service_id,stage_id), FOREIGN KEY(service_id) REFERENCES services(id), FOREIGN KEY(stage_id) REFERENCES stages(id), FOREIGN KEY(team_id) REFERENCES teams(id));
CREATE TABLE user_sectors (user_id CHAR(36), sector_id CHAR(36), PRIMARY KEY(user_id,sector_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(sector_id) REFERENCES sectors(id));
CREATE TABLE questions (id CHAR(36) PRIMARY KEY, created_by CHAR(36), stage_id CHAR(36), team_id CHAR(36), type ENUM('rating','text','single_choice','multiple_choice') NOT NULL DEFAULT 'rating', status ENUM('pending','approved','active','inactive','rejected') NOT NULL DEFAULT 'pending', current_version INT NOT NULL DEFAULT 1, is_required BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(stage_id) REFERENCES stages(id), FOREIGN KEY(team_id) REFERENCES teams(id));
CREATE TABLE question_versions (id CHAR(36) PRIMARY KEY, question_id CHAR(36) NOT NULL, version INT NOT NULL, prompt TEXT NOT NULL, change_reason TEXT, created_by CHAR(36), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(question_id,version), FOREIGN KEY(question_id) REFERENCES questions(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE question_options (id CHAR(36) PRIMARY KEY, question_version_id CHAR(36) NOT NULL, label VARCHAR(255) NOT NULL, value VARCHAR(100) NOT NULL, display_order INT DEFAULT 0, FOREIGN KEY(question_version_id) REFERENCES question_versions(id));
CREATE TABLE question_assignments (id CHAR(36) PRIMARY KEY, question_id CHAR(36) NOT NULL, sector_id CHAR(36), service_id CHAR(36), stage_id CHAR(36), display_order INT DEFAULT 0, is_active BOOLEAN DEFAULT TRUE, FOREIGN KEY(question_id) REFERENCES questions(id), FOREIGN KEY(sector_id) REFERENCES sectors(id), FOREIGN KEY(service_id) REFERENCES services(id), FOREIGN KEY(stage_id) REFERENCES stages(id));
CREATE TABLE question_approvals (id CHAR(36) PRIMARY KEY, question_id CHAR(36) NOT NULL, reviewer_id CHAR(36) NOT NULL, action ENUM('approved','rejected') NOT NULL, justification TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(question_id) REFERENCES questions(id), FOREIGN KEY(reviewer_id) REFERENCES users(id));
CREATE TABLE surveys (id CHAR(36) PRIMARY KEY, access_token_hash CHAR(64) NOT NULL UNIQUE, status ENUM('draft','in_progress','completed','expired') DEFAULT 'draft', started_at DATETIME, completed_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE survey_attendances (id CHAR(36) PRIMARY KEY, survey_id CHAR(36) NOT NULL, sector_id CHAR(36) NOT NULL, service_id CHAR(36) NOT NULL, shift_id CHAR(36) NOT NULL, attendance_date DATE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(survey_id) REFERENCES surveys(id), FOREIGN KEY(sector_id) REFERENCES sectors(id), FOREIGN KEY(service_id) REFERENCES services(id), FOREIGN KEY(shift_id) REFERENCES shifts(id));
CREATE TABLE survey_questions (id CHAR(36) PRIMARY KEY, survey_id CHAR(36) NOT NULL, attendance_id CHAR(36), question_id CHAR(36), question_version_id CHAR(36), prompt_snapshot TEXT NOT NULL, type_snapshot VARCHAR(30) NOT NULL, required_snapshot BOOLEAN NOT NULL, display_order INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(survey_id) REFERENCES surveys(id), FOREIGN KEY(attendance_id) REFERENCES survey_attendances(id));
CREATE TABLE answers (id CHAR(36) PRIMARY KEY, survey_question_id CHAR(36) NOT NULL UNIQUE, rating_value DECIMAL(5,2), text_value TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(survey_question_id) REFERENCES survey_questions(id));
CREATE TABLE feedback (id CHAR(36) PRIMARY KEY, survey_id CHAR(36) NOT NULL UNIQUE, positive_text TEXT, negative_text TEXT, praise_text TEXT, suggestion_text TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(survey_id) REFERENCES surveys(id));
CREATE TABLE return_requests (id CHAR(36) PRIMARY KEY, survey_id CHAR(36) NOT NULL UNIQUE, name VARCHAR(150), contact VARCHAR(255) NOT NULL, preferred_channel VARCHAR(30), message TEXT, status ENUM('open','in_progress','closed') DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(survey_id) REFERENCES surveys(id));
CREATE TABLE invitations (id CHAR(36) PRIMARY KEY, token_hash CHAR(64) UNIQUE NOT NULL, channel ENUM('email','whatsapp','manual') NOT NULL, contact VARCHAR(255), expires_at DATETIME NOT NULL, used_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notification_logs (id CHAR(36) PRIMARY KEY, invitation_id CHAR(36), channel VARCHAR(30), status VARCHAR(30), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invitation_id) REFERENCES invitations(id));
CREATE TABLE attendance_counts (id CHAR(36) PRIMARY KEY, sector_id CHAR(36), service_id CHAR(36), count_date DATE NOT NULL, total INT NOT NULL, UNIQUE(sector_id,service_id,count_date));
CREATE TABLE refresh_tokens (id CHAR(36) PRIMARY KEY DEFAULT (UUID()), user_id CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, revoked_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE audit_logs (id CHAR(36) PRIMARY KEY, user_id CHAR(36), action VARCHAR(100) NOT NULL, entity VARCHAR(100), entity_id CHAR(36), metadata JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
